    "customBtnFont": "font-lora",
    "customBorderColor": "#1f1c15",
    "authorUid": "ePOrKF7a6fhoWMkVE6d067X3TCf1",
    "editorPhoto": "data:image/png;base64,",
    "authorEmail": "askerhater21@gmail.com",
